<template>
  <div class="chart-card">
    <!-- 只有一张曲绘时就是普通图片；多张时叠两层做淡入淡出 -->
    <img v-if="!rotating" :src="chartInfo[2]" :alt="chartInfo[3]" class="cover-img" loading="lazy" />
    <template v-else>
      <img
        :src="layers[0]"
        :alt="chartInfo[3]"
        class="cover-img cover-layer"
        :class="{ 'is-active': active === 0 }"
        loading="lazy"
      />
      <img
        :src="layers[1]"
        :alt="chartInfo[3]"
        class="cover-img cover-layer"
        :class="{ 'is-active': active === 1 }"
        loading="lazy"
      />
    </template>
    <div class="card-shade"></div>
    <div class="card-info">
      <span
        class="dt-chip difficulty-tag"
        :style="{ '--chip-color': chartInfo[4] || 'var(--dt-text-dim)' }"
      >{{ chartInfo[3] }}</span>
    </div>
    <!-- 曲名压在曲绘上方但文字完全透明，看不见，只给浏览器 Ctrl+F 搜索定位 -->
    <span class="dt-cover-name">{{ chartInfo[5] }}</span>
  </div>
</template>

<script setup>
import { computed, onUnmounted, ref, watch } from 'vue'

/*
 * 定数/谱面卡片：曲绘铺底，右下角挂难度标签。
 * chartInfo 的字段顺序由 api/levels.js 决定：[曲目键名, 定数, 曲绘, 难度标签, 难度颜色, 曲名]。
 * 曲名不显示，只作为不可见文本供 Ctrl+F 搜索。
 * covers 可选：同一版里有多张曲绘时（愚人节差分图）每 5 秒轮换一张，切换用淡入淡出。
 */
const props = defineProps({
  chartInfo: {
    type: Array,
    required: true
  },
  covers: {
    type: Array,
    default: null
  }
})

// 两张叠图各存一张曲绘，active 指向当前可见的那层；轮换时让另一层换成下一张再翻过去
const layers = ref(['', ''])
const active = ref(0)
const index = ref(0)
let timer = null

const rotating = computed(() => Boolean(props.covers && props.covers.length > 1))

const stop = () => {
  if (timer) {
    clearInterval(timer)
    timer = null
  }
}

const advance = () => {
  if (!rotating.value) return
  index.value = (index.value + 1) % props.covers.length
  const back = 1 - active.value
  const next = layers.value.slice()
  next[back] = props.covers[index.value]
  layers.value = next
  active.value = back
}

const start = () => {
  stop()
  index.value = 0
  active.value = 0
  if (rotating.value) {
    // 两张图一开始就都挂上，第二张会立刻加载，轮到它时不会空一帧
    layers.value = [props.covers[0], props.covers[1 % props.covers.length]]
    timer = setInterval(advance, 5000)
  } else {
    layers.value = [props.chartInfo[2], props.chartInfo[2]]
  }
}

watch(() => props.covers, start, { immediate: true })
onUnmounted(stop)
</script>

<style scoped>
.chart-card {
  position: relative;
  aspect-ratio: 256 / 135;
  border-radius: var(--dt-radius-sm);
  overflow: hidden;
  background: var(--dt-bg-layer-2);
  border: 1px solid var(--dt-border);
  transition:
    transform var(--dt-dur-fast) var(--dt-ease-out),
    border-color var(--dt-dur-fast) var(--dt-ease-out);
}

.chart-card:hover {
  transform: translateY(-2px);
  border-color: var(--dt-border-strong);
}

.cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  filter: brightness(0.92);
}

/* 多张曲绘轮换：两层交叉淡入淡出（曲绘切换本身就是动效，这里不用位移/渐入令牌） */
.cover-layer {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.6s var(--dt-ease);
}

.cover-layer.is-active {
  opacity: 1;
}

/* 底部压暗，让难度标签压在曲绘上也看得清 */
.card-shade {
  position: absolute;
  inset: auto 0 0 0;
  height: 45%;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.55), transparent);
  pointer-events: none;
}

.card-info {
  position: absolute;
  inset: auto 0 0 0;
  display: flex;
  justify-content: flex-end;
  padding: 0.08rem;
}

.difficulty-tag {
  justify-content: center;
  min-width: 0.42rem;
  padding-inline: calc(var(--dt-space-2) * 1.4);
  letter-spacing: 0.02em;
  background: var(--chip-color);
  border: 1px solid rgba(0, 0, 0, 0.25);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
  font-weight: 700;
}</style>
